CREATE DATABASE IF NOT EXISTS oms_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE oms_db;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS order_items; DROP TABLE IF EXISTS payments; DROP TABLE IF EXISTS orders; DROP TABLE IF EXISTS products; DROP TABLE IF EXISTS users;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role ENUM('admin','sales','warehouse','shipping_staff','report_staff','confirmation_staff','customer') NOT NULL DEFAULT 'customer',address VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE products(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,description TEXT,price DECIMAL(10,2) NOT NULL DEFAULT 0,stock INT NOT NULL DEFAULT 0,weight DECIMAL(8,2) DEFAULT 0,tax_rate DECIMAL(5,2) DEFAULT 18,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE orders(id INT AUTO_INCREMENT PRIMARY KEY,customer_id INT NOT NULL,order_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,status ENUM('Pending','Accepted','Rejected','Processing','Shipped','Delivered','Cancelled') DEFAULT 'Pending',subtotal DECIMAL(10,2) DEFAULT 0,tax DECIMAL(10,2) DEFAULT 0,total DECIMAL(10,2) DEFAULT 0,shipping_address VARCHAR(255),confirmed_by INT NULL,shipped_by INT NULL,shipped_at DATETIME NULL,FOREIGN KEY(customer_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(confirmed_by) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(shipped_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE order_items(id INT AUTO_INCREMENT PRIMARY KEY,order_id INT NOT NULL,product_id INT NOT NULL,quantity INT NOT NULL,unit_price DECIMAL(10,2) NOT NULL,tax_rate DECIMAL(5,2) DEFAULT 18,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE payments(id INT AUTO_INCREMENT PRIMARY KEY,order_id INT NOT NULL,method ENUM('Cash on Delivery','Online') NOT NULL,amount DECIMAL(10,2) NOT NULL,status ENUM('Pending','Paid','Failed') DEFAULT 'Pending',transaction_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE);
